head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[tr > P > id]<br/>tr 의 ID 를 설정합니다.",
    "validation" : [
        "tr 을 구별할 수 있는 유일값을 문자열로 설정할 수 있어야 합니다.",
        "속성명이나 메소드명과 같은 예약어를 설정할 경우 오류가 발생할 수 있습니다."
    ]
}



scwin.onpageload = function () {
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    scwin.comp_init();
};



// comp 생성 (tableLayout 의 1행(이름/부서) tr 이 검증 대상)
scwin.comp_init = async function () {
    $c.gcm.createLabel('label="ID 는 테이블 1행(이름 / 부서) tr 에 적용됩니다.\n[절차] ID 입력 -> Target 재생성 -> getID\n[참고] 예약어(예: scwin, $p) 입력 후 Target 재생성 시 버튼 동작과 콘솔 오류 확인"', '', 'label1');

    // 기존 table 있으면 삭제 (하위 tr/th/td 포함)
    if (typeof scwin.tbl1 !== 'undefined') {
        scwin.tbl1.remove();
    }

    // 조건 설정
    let cID = con_ID.getValue();

    // comp 생성 : 첫 번째 tr 에 id 적용
    scwin.tbl1 = await $c.gcm.createBasicTableLayout('', '', 'tbl1', '', { tr: 'id="' + cID + '"' });
    scwin.target1 = scwin.tbl1._sub.tr;
};



// validation 1, 2 판정 출력 : getID 반환값과 렌더된 tr 의 id
scwin.btn_getID_onclick = function (e) {
    let objRender = scwin.target1.render;

    wf_body_bottom.getObj("scwin").setReturnValue("getID() : " + scwin.target1.getID() + " / tr id : " + (objRender ? objRender.id : objRender));
};
